interface.definition:
a!localVariables(
  #"SYSTEM_SYSRULES_sectionLayout_v1"(
    contents: {
      #"SYSTEM_SYSRULES_columnsLayout"(
        columns: {
          #"SYSTEM_SYSRULES_columnLayout"(
            contents: {
              #"SYSTEM_SYSRULES_cardLayout"(
                contents: {
                  #"SYSTEM_SYSRULES_richTextDisplayField"(
                    value: {
                      #"SYSTEM_SYSRULES_richTextIcon"(icon: "WARNING", color: "NEGATIVE"),
                      char(9),
                      #"SYSTEM_SYSRULES_richTextItem_v1"(
                        text: "User is currently deactivated in Appian",
                        style: "STRONG",
                        color: "STANDARD",
                        size: "MEDIUM"
                      )
                    }
                  )
                },
                showBorder: false,

              ),

            }
          ),
          #"SYSTEM_SYSRULES_columnLayout"()
        }
      ),
      #"SYSTEM_SYSRULES_sectionLayout_v1"(),
      #"SYSTEM_SYSRULES_ButtonLayout"(
        primaryButtons: {
          #"SYSTEM_SYSRULES_buttonWidget_v1"(
            label: "REACTIVATE",
            submit: true,
            style: "SOLID",
            validate: true,
            value: "Reactivate",
            saveInto: {
              ri!buttonValue,
              a!save(
                ri!rolesLocal,
                #"urn:appian:function:v1:a:update"(ri!rolesLocal, "appianStatus", true)
              ),
              a!save(ri!rolesRecord,ri!rolesLocal),
              a!save(
                ri!userRecordLocal,
                #"urn:appian:function:v1:a:update"(
                  ri!userRecordLocal,
                  {"modifiedBy","modifiedOn"},
                  {loggedInUser(),now()}
                )
              ),
              a!save(
                ri!userRecord,ri!userRecordLocal
              )
            }
          )
        },
        secondaryButtons: {
          #"SYSTEM_SYSRULES_buttonWidget_v1"(
            label: "Cancel",
            submit: true,
            value: "Cancel",
            saveInto: ri!buttonValue
          )
        }
      )
    }
  )
)
